<script setup lang="ts">
import { computed } from 'vue'
import { useRoute } from 'vue-router'
import { ArrowLeftOutlined, ArrowRightOutlined, CheckOutlined, CloudUploadOutlined, CodeOutlined, CopyOutlined, FileImageOutlined, SafetyCertificateOutlined } from '@ant-design/icons-vue'
import { copyText } from '../services/upload'
import { Wstoast } from '../services/toast'
const route = useRoute()
const page = computed(() => String(route.meta.page || 'models'))
const endpoint = `${window.location.origin}/api/upload`
const curl = `curl -X POST "${endpoint}" \\\n  -F "action=upload-img" \\\n  -F "ft=imgbb" \\\n  -F "file[]=@/path/to/image.png"`
const providers = [
  { name: 'ImgBB', key: 'imgbb', desc: 'Nguồn mặc định của bản gốc, trả về URL ảnh trực tiếp.', color: '#16a34a' },
  { name: 'Sohu', key: 'sohu', desc: 'Chuyển tiếp ảnh qua Changyan Sohu attachment API.', color: '#2563eb' },
  { name: 'Imgur', key: 'imgur', desc: 'Imgur API v3, Client ID được giữ phía server.', color: '#8b5cf6' },
  { name: 'Telegra.ph', key: 'telegra', desc: 'Tải ảnh lên Telegra.ph và nhận đường dẫn công khai.', color: '#0ea5e9' }
]
async function copyCode() {
  try { await copyText(curl); Wstoast.success('Đã sao chép vào bộ nhớ tạm!') }
  catch { Wstoast.error('Lỗi khi sao chép vào bộ nhớ tạm!') }
}
</script>

<template>
  <div class="info-page">
    <header class="info-header"><RouterLink to="/" class="info-brand"><img src="/logo.png" alt="" /><span>WsUploadPicture</span></RouterLink><nav><RouterLink to="/models">Providers</RouterLink><RouterLink to="/docs">Docs</RouterLink><RouterLink to="/terms">Terms</RouterLink></nav><RouterLink to="/upload" class="info-open">Open Uploader <ArrowRightOutlined /></RouterLink></header>
    <main class="info-main">
      <RouterLink to="/" class="info-back"><ArrowLeftOutlined /> Back to home</RouterLink>
      <template v-if="page === 'models'">
        <section class="info-hero"><span class="info-kicker"><CloudUploadOutlined /> IMAGE PROVIDERS</span><h1>Four sources.<br /><span>One simple upload.</span></h1><p>Chọn nhà cung cấp phù hợp. Request được xử lý phía server và trả về cùng định dạng kết quả với source gốc.</p></section>
        <section class="provider-grid"><article v-for="item in providers" :key="item.key"><div class="provider-grid__top"><FileImageOutlined :style="{ color:item.color }" /><code>{{ item.key }}</code></div><h2>{{ item.name }}</h2><p>{{ item.desc }}</p><span><CheckOutlined /> JPG, PNG, GIF · tối đa 5 MB</span></article></section>
      </template>
      <template v-else-if="page === 'docs'">
        <section class="info-hero"><span class="info-kicker"><CodeOutlined /> API DOCUMENTATION</span><h1>Upload with<br /><span>one request.</span></h1><p>Gửi multipart/form-data tới <code>/api/upload</code>. Endpoint <code>/upload.php</code> vẫn được hỗ trợ để tương thích.</p></section>
        <section class="docs-layout"><article><h2>Form fields</h2><div class="params"><div><strong>action</strong><code>upload-img</code></div><div><strong>ft</strong><code>imgbb | sohu | imgur | telegra</code></div><div><strong>file[]</strong><code>Một hoặc nhiều File, tối đa 5 MB</code></div></div><h2>Success response</h2><pre>{
  "status": "success",
  "data": [{ "name": "image.png", "size": "0.02 MB", "link": "https://..." }],
  "msg": "Uploaded successfully!"
}</pre></article><aside class="code-card"><div><span>cURL</span><button @click="copyCode"><CopyOutlined /> Copy</button></div><pre>{{ curl }}</pre><p><SafetyCertificateOutlined /> Secret chỉ được đọc phía server.</p></aside></section>
      </template>
      <template v-else-if="page === 'terms'">
        <section class="info-hero"><span class="info-kicker">TERMS OF USE</span><h1>Simple terms.<br /><span>Clear responsibility.</span></h1><p>Cập nhật ngày 06/11/2026.</p></section>
        <section class="terms-content"><article><span>01</span><div><h2>Nội dung bạn tải lên</h2><p>Chỉ tải lên hình ảnh bạn có quyền sử dụng. Không tải nội dung vi phạm pháp luật, xâm phạm quyền riêng tư hoặc sở hữu trí tuệ.</p></div></article><article><span>02</span><div><h2>Dịch vụ bên thứ ba</h2><p>Ảnh được gửi trực tiếp đến nhà cung cấp đã chọn. Thời gian lưu trữ, khả dụng và điều khoản của nhà cung cấp được áp dụng.</p></div></article><article><span>03</span><div><h2>Giới hạn</h2><p>Mỗi ảnh tối đa 5 MB và phải là PNG, JPEG hoặc GIF hợp lệ. Link ảnh không được bảo đảm tồn tại vĩnh viễn.</p></div></article></section>
      </template>
      <template v-else>
        <section class="info-hero info-hero--center"><span class="info-kicker">PRICING</span><h1>Free to upload.<br /><span>Zero setup.</span></h1><p>Không có gói trả phí trong công cụ này.</p></section>
        <section class="pricing-card"><span>FREE TO USE</span><div>$0<small>/ month</small></div><p>Dành cho việc lấy link ảnh nhanh chóng.</p><ul><li><CheckOutlined /> 4 nhà cung cấp lưu trữ</li><li><CheckOutlined /> Upload nhiều ảnh cùng lúc</li><li><CheckOutlined /> Không cần tài khoản</li><li><CheckOutlined /> Tối đa 5 MB mỗi ảnh</li></ul><RouterLink to="/upload">Start uploading <ArrowRightOutlined /></RouterLink></section>
      </template>
      <div class="info-cta"><div><h2>Sẵn sàng tải ảnh?</h2><p>Không đăng ký, không cài đặt.</p></div><RouterLink to="/upload">Upload an image <ArrowRightOutlined /></RouterLink></div>
    </main>
    <footer class="info-footer">© {{ new Date().getFullYear() }} WsUploadPicture · Vue 3 + Anime.js</footer>
  </div>
</template>

